<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_super_admin();
$keys=['company_name','company_gstin','company_address','company_state_code','invoice_prefix','cashier_max_discount_pct','manager_max_discount_pct','session_timeout_minutes'];$err='';$msg=isset($_GET['saved'])?'Settings saved.':'';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{foreach($keys as $k){$v=trim((string)($_POST[$k]??''));if($k==='company_state_code'&&$v!==''&&!preg_match('/^\d{2}$/',$v))throw new Exception('Company State Code must be exactly 2 digits.');if($k==='company_gstin')$v=strtoupper($v);if(in_array($k,['cashier_max_discount_pct','manager_max_discount_pct'],true)&&((float)$v<0||(float)$v>100))throw new Exception('Discount limits must be 0-100.');if($k==='session_timeout_minutes'&&(int)$v<5)throw new Exception('Session timeout must be at least 5 minutes.');db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,$v]);}audit('SETTINGS_UPDATE','settings',null);redirect('settings.php?saved=1');}catch(Throwable $e){$err=$e->getMessage();}}
$vals=[];foreach($keys as $k)$vals[$k]=setting($k,'');page_header('Company & Security Settings');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row3"><div><label>Company Name</label><input name="company_name" value="<?=e($vals['company_name'])?>" required></div><div><label>GSTIN</label><input name="company_gstin" value="<?=e($vals['company_gstin'])?>"></div><div><label>Home State Code</label><input name="company_state_code" maxlength="2" value="<?=e($vals['company_state_code'])?>" placeholder="36"></div></div><br><div class="row"><div><label>Company Address</label><textarea name="company_address" rows="3"><?=e($vals['company_address'])?></textarea></div><div><label>Invoice Prefix</label><input name="invoice_prefix" value="<?=e($vals['invoice_prefix'])?>"></div></div><br><div class="row3"><div><label>Cashier Max Discount %</label><input type="number" step="0.01" min="0" max="100" name="cashier_max_discount_pct" value="<?=e($vals['cashier_max_discount_pct'])?>"></div><div><label>Manager Max Discount %</label><input type="number" step="0.01" min="0" max="100" name="manager_max_discount_pct" value="<?=e($vals['manager_max_discount_pct'])?>"></div><div><label>Session Timeout Minutes</label><input type="number" min="5" name="session_timeout_minutes" value="<?=e($vals['session_timeout_minutes'])?>"></div></div><br><button class="btn">Save Settings</button></form>
